const r=$input.first().json;
let t=r.output_text;

if(!t&&Array.isArray(r.output)){
  t=r.output
    .flatMap(x=>x.content||[])
    .map(x=>x.text||'')
    .join('');
}

t=String(t||'')
  .replace(/^```json\s*/i,'')
  .replace(/^```\s*/i,'')
  .replace(/\s*```$/i,'')
  .trim();

if(!t){
  throw new Error('Codex returned empty output.');
}

// ------------------------------------------------------------
// Extract first complete JSON object
// Handles nested objects/arrays and braces inside strings.
// ------------------------------------------------------------

function extractJsonObject(text){
  const start=text.indexOf('{');

  if(start===-1){
    throw new Error('No JSON object found in Codex output.');
  }

  let depth=0;
  let inString=false;
  let escaped=false;

  for(let i=start;i<text.length;i++){
    const ch=text[i];

    if(inString){
      if(escaped){
        escaped=false;
        continue;
      }

      if(ch==='\\'){
        escaped=true;
        continue;
      }

      if(ch==='"'){
        inString=false;
      }

      continue;
    }

    if(ch==='"'){
      inString=true;
      continue;
    }

    if(ch==='{'){
      depth++;
    }

    if(ch==='}'){
      depth--;

      if(depth===0){
        return text.slice(start,i+1);
      }
    }
  }

  throw new Error('Incomplete JSON object returned by Codex.');
}

const jsonText=extractJsonObject(t);

let o;

try{
  o=JSON.parse(jsonText);
}catch(e){
  throw new Error(
    'Invalid Codex JSON: '+e.message
  );
}

// ------------------------------------------------------------
// Required fields
// ------------------------------------------------------------

const k=[
  'Required Yrs Experience',
  'Salary',
  'No. of Applicants',
  'Job Posted Date',
  'Location',
  'Work Mode',
  'Job Description',
  'Matching %',
  'Matching Reason',
  'Missing Skills',
  'Resume Keywords',
  'Referral Message',
  'Tailored Resume LaTeX'
];

for(const x of k){
  if(!(x in o)){
    throw new Error(
      'Missing field: '+x
    );
  }
}

// ------------------------------------------------------------
// Matching %
// ------------------------------------------------------------

o['Matching %']=Number(
  o['Matching %']??0
);

if(
  Number.isNaN(o['Matching %']) ||
  o['Matching %']<0 ||
  o['Matching %']>100
){
  throw new Error(
    'Matching % must be a number between 0 and 100.'
  );
}

// ------------------------------------------------------------
// Arrays
// ------------------------------------------------------------

if(!Array.isArray(o['Missing Skills'])){
  o['Missing Skills']=[];
}

if(!Array.isArray(o['Resume Keywords'])){
  o['Resume Keywords']=[];
}

// ------------------------------------------------------------
// Getting Previous Item
// ------------------------------------------------------------

const prev_item = $("Prepare Item data").item.json

// ------------------------------------------------------------
// Referral message
// ------------------------------------------------------------

if(
  String(o['Referral Message']||'').length>500
){
  throw new Error(
    'Referral Message exceeds 500 characters.'
  );
}

// ------------------------------------------------------------
// LaTeX validation
// ------------------------------------------------------------

const latex=String(
  o['Tailored Resume LaTeX']||''
);

if(
  !latex.includes('\\documentclass') ||
  !latex.includes('\\end{document}')
){
  throw new Error(
    'Incomplete LaTeX.'
  );
}

// ------------------------------------------------------------
// Return
// ------------------------------------------------------------

return[
  {
    json: {
      ...o,
      ...prev_item
    }
  }
];

const a = $('Prepare Resume File').item.json;
const u = $input.first().json;

const link = u.webContentLink || u.webViewLink;

if (!link) {
  throw new Error('Drive upload returned no web link.');
}

return [{
  json: {
    'S.No': a['S.No'],
    'Company': a['Company'],
    'Role': a['Role'],
    'Required Yrs Experience': a['Required Yrs Experience'],
    'Salary': a['Salary'],
    'Application Link': a['Application link'],
    'No. of Applicants': a['No. of Applicants'],
    'Job Posted Date': a['Job Posted Date'],
    'Location': a['Location'],
    'Work Mode': a['Work Mode'],
    'Job Description': a['Job Description'],
    'Matching %': a['Matching %'],
    'Matching Reason': a['Matching Reason'],
    'Missing Skills': Array.isArray(a['Missing Skills'])
      ? a['Missing Skills'].join(', ')
      : '',
    'Resume Keywords': Array.isArray(a['Resume Keywords'])
      ? a['Resume Keywords'].join(', ')
      : '',
    'Referral Leads': a.referral_leads,
    'Referral Message': a['Referral Message'],
    'Tailored Resume Link': link,
    'Application Status': 'Not Applied'
  }
}];

const item = $input.first();

if (!item.binary?.data) {
  throw new Error(
    'No binary file "data" received from Read/Write Files from Disk.'
  );
}

// Read actual file contents
const buffer =
  await this.helpers.getBinaryDataBuffer(0, 'data');

const stdout =
  buffer.toString('utf8').trim();

if (!stdout) {
  throw new Error('dummy-output.txt is empty.');
}

// ============================================================
// APPLICATION PAGE
// ============================================================

let result;

try {
  result = JSON.parse(stdout);
} catch (error) {
  throw new Error(
    'agent.mjs output is not valid JSON: ' +
    error.message +
    '\n\nFirst 2500 characters:\n' +
    stdout.slice(0, 2500)
  );
}

if (result.error) {
  throw new Error(
    result.message || 'Browser agent failed.'
  );
}

const scrapedHtml =
  String(result.html || '');

if (!scrapedHtml) {
  throw new Error(
    'agent.mjs returned no HTML.'
  );
}

// ============================================================
// CLEAN HTML
// ============================================================

const cleaned_web_page_data =
  scrapedHtml
    .replace(/<script[\s\S]*?<\/script>/gi, '')
    .replace(/<style[\s\S]*?<\/style>/gi, '')
    .replace(/<noscript[\s\S]*?<\/noscript>/gi, '')
    .replace(/<svg[\s\S]*?<\/svg>/gi, '')
    .replace(/<iframe[\s\S]*?<\/iframe>/gi, '')
    .replace(/<nav[\s\S]*?<\/nav>/gi, '')
    .replace(/<footer[\s\S]*?<\/footer>/gi, '')
    .replace(
      /<\/(div|p|section|article|li|h1|h2|h3|h4|h5|h6|br|tr)>/gi,
      '\n'
    )
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;/gi, "'")
    .replace(/[ \t]+/g, ' ')
    .replace(/\n\s*\n+/g, '\n')
    .trim()
    .slice(0, 100000);

// ============================================================
// RETURN APPLICATION PAGE DATA
// ============================================================


const prev_item = {...$('Loop Over Items').item.json}

const company = String(prev_item["Company"] || '').trim();

const recruiterSearchUrl =
  'https://www.linkedin.com/search/results/people/?keywords=' +
  encodeURIComponent(`${company} recruiter`) +
  '&origin=GLOBAL_SEARCH_HEADER';

const employeeSearchUrl =
  'https://www.linkedin.com/search/results/people/?keywords=' +
  encodeURIComponent(`Software Engineer at ${company}`) +
  '&origin=GLOBAL_SEARCH_HEADER';

const referral_leads = `Recruiters=${recruiterSearchUrl}|Employees=${employeeSearchUrl}`

return [
  {
    json: {
      ...prev_item,
      application_link: prev_item["Application link"],
      referral_leads,
      scraped_job_page: cleaned_web_page_data
    }
  }
];
